import re
import glob
from collections import Counter

import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_XLSX = '/app/workspace/stat_ocr.xlsx'

MONEY_STRICT = re.compile(r'(?<![\d.])(\d{1,3}(?:,\d{3})+|\d+)\.(\d{2})(?![\d.])')


def parse_money_from_line(line):
    """Return the last plausible monetary value on a line as float, or None."""
    s = line.replace('"', '').replace('~', '').replace('—', '')
    matches = list(MONEY_STRICT.finditer(s))
    if matches:
        m = matches[-1]
        return float(m.group(1).replace(',', '') + '.' + m.group(2))
    # colon-as-decimal repair
    s2 = re.sub(r'(\d)[:](\d{2})\b', r'\1.\2', s)
    m = MONEY_STRICT.search(s2)
    if m:
        return float(m.group(1).replace(',', '') + '.' + m.group(2))
    # 'u' as 0 in a strict-like pattern e.g. 15.u00
    s3 = s.replace('u', '0').replace('U', '0')
    matches = list(MONEY_STRICT.finditer(s3))
    if matches:
        m = matches[-1]
        return float(m.group(1).replace(',', '') + '.' + m.group(2))
    return None


EXCLUDE_KWS = [
    'SUBTOTAL', 'SUB TOTAL', 'SUB-TOTAL', 'SUB-TUTAL',
    'TAX', 'GST', 'SST',
    'DISCOUNT', 'CHANGE', 'CASH TENDERED',
]

# priority tiers (higher first)
TIERS = [
    ['GRAND TOTAL', 'GRANDTOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]


def find_total(text):
    lines = [ln.rstrip() for ln in text.split('\n')]
    for tier in TIERS:
        best = None
        best_idx = -1
        for i, ln in enumerate(lines):
            up = ln.upper()
            if not any(k in up for k in tier):
                continue
            # exclude if any exclude keyword is present, unless a stronger keyword in tier is also present.
            # Special-case: 'GRAND TOTAL' should still win even if line has other words.
            if any(ex in up for ex in EXCLUDE_KWS):
                # If tier is the GRAND TOTAL tier, keep going (grand overrides).
                if tier is TIERS[0]:
                    pass
                else:
                    continue
            val = parse_money_from_line(ln)
            if val is None:
                # try next non-blank line
                for j in range(i + 1, min(i + 3, len(lines))):
                    if lines[j].strip():
                        val = parse_money_from_line(lines[j])
                        if val is not None:
                            break
            if val is not None:
                # keep the last match in this tier (final total)
                best = val
                best_idx = i
        if best is not None:
            return best
    return None


DATE_PATTERNS = [
    # dd-mm-yyyy or dd/mm/yyyy
    (re.compile(r'\b(\d{1,2})[-/](\d{1,2})[-/](\d{4})\b'), 'dmy4'),
    (re.compile(r'\b(\d{1,2})[-/](\d{1,2})[-/](\d{2})\b'), 'dmy2'),
    (re.compile(r'\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b'), 'ymd'),
]


def find_date(text):
    for line in text.split('\n'):
        for pat, kind in DATE_PATTERNS:
            m = pat.search(line)
            if m:
                if kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                else:
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    if kind == 'dmy2':
                        y = 2000 + y if y < 70 else 1900 + y
                if 1 <= mo <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099:
                    return f'{y:04d}-{mo:02d}-{d:02d}'
    return None


def ocr_variants(img):
    w, h = img.size
    gray = ImageOps.grayscale(img)
    variants = [
        img,
        ImageOps.autocontrast(gray),
        ImageOps.autocontrast(img.resize((w * 2, h * 2), Image.LANCZOS).convert('L')),
        ImageOps.autocontrast(img.resize((w * 3, h * 3), Image.LANCZOS).convert('L')),
        gray.filter(ImageFilter.SHARPEN),
    ]
    texts = []
    for v in variants:
        for psm in ['--psm 6', '--psm 4', '--psm 11']:
            try:
                t = pytesseract.image_to_string(v, config=psm)
                if t.strip():
                    texts.append(t)
            except Exception:
                pass
    return texts


def process(path):
    img = Image.open(path)
    texts = ocr_variants(img)

    date_votes = Counter()
    total_votes = Counter()
    for t in texts:
        d = find_date(t)
        if d:
            date_votes[d] += 1
        tot = find_total(t)
        if tot is not None:
            total_votes[f'{tot:.2f}'] += 1

    date = date_votes.most_common(1)[0][0] if date_votes else None
    total = total_votes.most_common(1)[0][0] if total_votes else None
    return date, total


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])

    files = sorted(glob.glob(os.path.join(IMG_DIR, '*.jpg')))
    for p in files:
        name = os.path.basename(p)
        d, t = process(p)
        print(name, d, t)
        ws.append([name, d, t])

    wb.save(OUT_XLSX)


if __name__ == '__main__':
    main()
